mapper.select:
select
a.device_id,
a.mete_id,
a.mete_name,
a.mete_index,
a.mete_cid,
a.control_status,
a.enable_string,
a.succeed_string,
a.trigger_string,
a.control_value,
a.mete_code,
a.device_type,
a.description,
a.describer
from t_cfg_telecontrol a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=VARCHAR}
 and a.mete_id = #{meteId, jdbcType=VARCHAR}
 and a.mete_name = #{meteName, jdbcType=VARCHAR}
 and a.mete_index = #{meteIndex, jdbcType=INTEGER}
 and a.mete_cid = #{meteCid, jdbcType=INTEGER}
 and a.control_status = #{controlStatus, jdbcType=INTEGER}
 and a.enable_string = #{enableString, jdbcType=VARCHAR}
 and a.succeed_string = #{succeedString, jdbcType=VARCHAR}
 and a.trigger_string = #{triggerString, jdbcType=VARCHAR}
 and a.control_value = #{controlValue, jdbcType=INTEGER}
 and a.mete_code = #{meteCode, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=VARCHAR}
 and a.description = #{description, jdbcType=VARCHAR}
 and a.describer = #{describer, jdbcType=VARCHAR}

